Uso: python -I epmc_lookup.py arquivo_de_titulos.txt
Uma consulta por linha. Linha vazia ou iniciada por # e ignorada.
"""

import json
import sys
import time
import urllib.parse
import urllib.request

EPMC = "https://www.ebi.ac.uk/europepmc/webservices/rest/search"


def consulta(termo: str, n: int = 4) -> list[dict]:
    params = urllib.parse.urlencode(
        {"query": termo, "format": "json", "resultType": "lite", "pageSize": n}
    )
    req = urllib.request.Request(
        f"{EPMC}?{params}", headers={"User-Agent": "bio-stack-biblio/1.0"}
    )
    with urllib.request.urlopen(req, timeout=60) as resp:
        dados = json.load(resp)
    return dados.get("resultList", {}).get("result", [])


def main() -> int:
    linhas = [
        linha.strip()
        for linha in open(sys.argv[1], encoding="utf-8")
        if linha.strip() and not linha.startswith("#")
    ]
    for termo in linhas:
        print(f"\n=== {termo}")
        try:
            hits = consulta(termo)
        except Exception as erro:  # rede instavel e o modo de falha real aqui
            print(f"    ERRO: {erro}")
            continue
        if not hits:
            print("    SEM RESULTADO")
        for h in hits:
            print(
                "    | {ano} | {rev} | {titulo}\n"
                "      doi={doi} pmid={pmid} pmcid={pmcid} oa={oa} ft={ft}".format(
                    ano=h.get("pubYear", "?"),
                    rev=h.get("journalTitle", "?")[:40],
                    titulo=h.get("title", "?")[:95],
                    doi=h.get("doi", ""),
                    pmid=h.get("pmid", ""),
                    pmcid=h.get("pmcid", ""),
                    oa=h.get("isOpenAccess", "?"),
                    ft=h.get("hasFreeFulltext", "?"),
                )
            )
        time.sleep(0.35)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

