"""Pergunta ao Europe PMC quais URLs de texto completo ele declara para cada PMCID.

Checar com curl da errado: cell.com, OUP e o proprio europepmc devolvem 403 para
cliente sem cara de navegador. O fullTextUrlList e a fonte declarada pelo EBI.
"""
from __future__ import annotations

import json
import sys
import urllib.error
import urllib.request

BASE = "https://www.ebi.ac.uk/europepmc/webservices/rest"


def _p(texto: str) -> None:
    print(texto.encode("ascii", "replace").decode("ascii"))


def lista(pmcid: str) -> dict:
    url = f"{BASE}/PMC/{pmcid}/fullTextUrlList?format=json"
    req = urllib.request.Request(url, headers={"User-Agent": "bio-stack-biblio/1.0"})
    with urllib.request.urlopen(req, timeout=40) as fh:
        return json.load(fh)


def main() -> int:
    for pmcid in [a.strip() for a in sys.argv[1:] if a.strip()]:
        try:
            dados = lista(pmcid)
        except urllib.error.HTTPError as erro:
            _p(f"{pmcid}: HTTP {erro.code}")
            continue
        except Exception as erro:
            _p(f"{pmcid}: FALHA {type(erro).__name__}: {erro}")
            continue
        itens = dados.get("fullTextUrlList", {}).get("fullTextUrl", [])
        _p(pmcid)
        for it in itens:
            _p(
                f"   [{it.get('availability','?')}/{it.get('availabilityCode','?')}]"
                f" {it.get('documentStyle','?')} {it.get('site','?')}: {it.get('url','')}"
            )
        if not itens:
            _p("   -- nenhuma URL declarada --")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

