// Recursos por rotulo. O WSL tem 20 nucleos e 15 GB; o teto em
// resourceLimits deixa folga para o Windows e para o daemon do Docker, e faz
// o Nextflow encolher pedidos maiores em vez de falhar.

process {
    cpus   = 1
    memory = 2.GB
    time   = 4.h

    resourceLimits = [cpus: 16, memory: 12.GB, time: 48.h]

    // 130-145: sinais (137 = OOM killer); 104 e 175: falhas transitorias de
    // container. Uma nova tentativa resolve; o resto e erro de verdade.
    errorStrategy = { task.exitStatus in ((130..145) + 104 + 175) ? 'retry' : 'finish' }
    maxRetries    = 1

    withLabel: 'process_single' {
