"""Imprime requires_dist e requires_python de versoes especificas no PyPI."""
import json
import sys
import urllib.request
from concurrent.futures import ThreadPoolExecutor


def get(url):
    req = urllib.request.Request(url, headers={"User-Agent": "bio-stack-verifier/0.1"})
    with urllib.request.urlopen(req, timeout=60) as r:
        return json.load(r)


def show(spec):
    pkg, ver = spec.split("==") if "==" in spec else (spec, None)
    url = f"https://pypi.org/pypi/{pkg}/{ver}/json" if ver else f"https://pypi.org/pypi/{pkg}/json"
    try:
        d = get(url)
    except Exception as e:  # noqa: BLE001
        return f"## {spec}: ERRO {e}"
    info = d["info"]
    rd = info.get("requires_dist") or []
    lines = [f"## {pkg}=={info['version']} requires_python={info.get('requires_python')}"]
    for r in rd:
        lines.append(f"   {r}")
    return "\n".join(lines)


if __name__ == "__main__":
    with ThreadPoolExecutor(8) as ex:
        for res in ex.map(show, sys.argv[1:]):
            print(res)

