"""Lista pacotes do uv.lock sem wheel instalavel em CPython 3.12 / win_amd64."""
import re
import sys
import tomllib

LOCK = sys.argv[1]
with open(LOCK, "rb") as fh:
    lock = tomllib.load(fh)


def applies_312_win(pkg):
    marks = pkg.get("resolution-markers")
    if not marks:
        return True
    return any(("3.12" in m and "win32" in m and "!=" not in m.split("win32")[0][-4:]) or m.startswith("python_full_version >= '3.12'") for m in marks)


def wheel_ok(fn):
    m = re.match(r".+-([^-]+)-([^-]+)-([^-]+)\.whl$", fn)
    if not m:
        return False
    py, abi, plat = m.groups()
    plats = plat.split(".")
    plat_ok = any(p in ("any", "win_amd64") for p in plats)
    if not plat_ok:
        return False
    pys = py.split(".")
    if any(p in ("py3", "py2.py3", "cp312") for p in pys):
        return True
    if abi == "abi3":
        for p in pys:
            mm = re.match(r"cp3(\d+)$", p)
            if mm and int(mm.group(1)) <= 12:
                return True
    return False


missing = []
for pkg in lock["package"]:
    if not applies_312_win(pkg):
        continue
    src = pkg.get("source", {})
    if "registry" not in src and "url" not in src:
        continue
    wheels = [w.get("url", "").rsplit("/", 1)[-1] for w in pkg.get("wheels", [])]
    if not any(wheel_ok(w.replace("%2B", "+")) for w in wheels):
        missing.append((pkg["name"], pkg["version"], len(wheels), "sdist" in pkg))

print(f"pacotes sem wheel cp312-win_amd64 compativel: {len(missing)}")
for name, ver, nw, has_sdist in missing:
    print(f"  {name} {ver} (wheels no lock: {nw}, sdist: {has_sdist})")

