"""Le arquivos DCF (VIEWS/PACKAGES do Bioconductor e CRAN) e imprime campos de pacotes escolhidos."""
import sys

FIELDS = ["Version", "License", "NeedsCompilation", "win.binary.ver", "SystemRequirements", "Date/Publication", "Packaged"]


def parse(path):
    recs, cur, last = {}, {}, None
    with open(path, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            line = line.rstrip("\n")
            if not line.strip():
                if "Package" in cur:
                    recs[cur["Package"]] = cur
                cur, last = {}, None
                continue
            if line[:1] in (" ", "\t") and last:
                cur[last] += " " + line.strip()
            elif ":" in line:
                k, v = line.split(":", 1)
                cur[k] = v.strip()
                last = k
    if "Package" in cur:
        recs[cur["Package"]] = cur
    return recs


if __name__ == "__main__":
    path = sys.argv[1]
    pkgs = sys.argv[2:]
    recs = parse(path)
    print(f"# {path}: {len(recs)} registros")
    for p in pkgs:
        r = recs.get(p)
        if not r:
            print(f"{p}: AUSENTE")
            continue
        vals = {f: r[f] for f in FIELDS if f in r}
        print(f"{p}: {vals}")

