def anaconda(ch_pkg):
    st, body = get(f"https://api.anaconda.org/package/{ch_pkg}")
    if st != 200:
        return ch_pkg, f"HTTP {st}"
    d = json.loads(body)
    latest = d.get("latest_version")
    files = [f for f in d.get("files", []) if f.get("version") == latest]
    subdirs = sorted({f.get("attrs", {}).get("subdir", "?") for f in files})
    ups = sorted(f.get("upload_time", "") for f in files)
    builds = sorted({f.get("attrs", {}).get("build", "?") for f in files})
    lic = d.get("license")
    return ch_pkg, f"latest={latest} subdirs={subdirs} first_upload={ups[:1]} last_upload={ups[-1:]} builds={builds[:6]} license={lic} n_versions={len(d.get('versions', []))}"

def pypi(pkg):
    st, body = get(f"https://pypi.org/pypi/{pkg}/json")
    if st != 200:
        return pkg, f"HTTP {st}"
    d = json.loads(body)
    info = d["info"]
    ver = info["version"]
    rel = d["releases"].get(ver, [])
    files = [(f["filename"], f["upload_time_iso_8601"]) for f in rel]
