#: Ordem dos campos no rotulo do IQ-TREE com os padroes do pipeline.
ROTULOS_PADRAO = ("alrt", "abayes", "ufboot")


def _suporte(clade: Clade, rotulos: tuple[str, ...]) -> tuple[float | None, float | None]:
    """
    (SH-aLRT, UFBoot) de um no interno. O rotulo do IQ-TREE so tem os campos
    pedidos, na ordem SH-aLRT/aBayes/UFBoot; `rotulos` diz quais (vem do
    resumo.json da execucao). Um numero so, sem barra, e a probabilidade local
    do wASTRAL ou um suporte unico — devolvido no segundo campo.
    """
    rotulo = clade.name if clade.name and not clade.is_terminal() else None
    if rotulo and "/" in rotulo:
        partes = rotulo.split("/")
        if len(partes) != len(rotulos):
            return None, None
        try:
            valores = dict(zip(rotulos, (float(p) for p in partes), strict=True))
        except ValueError:
            return None, None
        return valores.get("alrt"), valores.get("ufboot", valores.get("abayes"))
    if clade.confidence is not None:
        return None, float(clade.confidence)
    return None, None

