"""Gera o anexo do relatorio de pesquisa a partir do journal do workflow.

Uso: python gerar_anexo.py <journal.jsonl> <saida.md>

Tabela por dominio com cada candidato levantado, o veredito do verificador e
as correcoes aplicadas. E o catalogo completo que a sintese resume.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

TITULOS = {
    "filogenia": "Filogenética e filogenômica",
    "evolucao": "Evolução molecular, seleção e perda gênica",
    "genomica": "Genômica comparativa e aquisição de dados",
    "cli": "Ferramentas de linha de comando no WSL",
    "linguagens": "Linguagens e ambientes",
    "omica": "Análise ômica e estatística",
    "pesquisa": "Infraestrutura de pesquisa e literatura",
    "ia": "IA para biologia (local e hospedada)",
    "repro": "Reprodutibilidade, dados e execução",
}
STATUS = {
    "confirmado": "confirmado",
    "corrigido": "corrigido",
    "refutado": "**refutado**",
    "nao_verificavel": "não verificável",
    None: "sem veredito",
