from io import StringIO
from pathlib import Path
from Bio import Phylo

ROT = ("alrt", "abayes", "ufboot")

def _suporte(clade, rotulos):  # copia literal da versao revisada
    rotulo = clade.name if clade.name and not clade.is_terminal() else None
    if rotulo and "/" in rotulo:
        partes = rotulo.split("/")
        if len(partes) != len(rotulos):
            return None, None
        try:
            valores = dict(zip(rotulos, (float(p) for p in partes), strict=True))
        except ValueError:
            return None, None
        return valores.get("alrt"), valores.get("ufboot", valores.get("abayes"))
    if clade.confidence is not None:
        return None, float(clade.confidence)
    return None, None

def _forte(sh, ufb):
    if ufb is None:
        return False
    if ufb <= 1.0 and sh is None:
        return ufb >= 0.95
    return ufb >= 95 and (sh is None or sh >= 80)

def enraizar(arv, outgroup):
    nomes = {t.name for t in arv.get_terminals()}
    presentes = [o.strip() for o in outgroup.split(",") if o.strip() in nomes]
    if not presentes:
        arv.root_at_midpoint()
        return ""
    arv.root_with_outgroup(presentes[0])
    if len(presentes) > 1:
        arv.root_with_outgroup(arv.common_ancestor(*presentes))
    return ",".join(presentes)

