"""Copia literal das funcoes da versao REVISADA de scripts/filogenia/desenhar_arvore.py
(lida as ~22:36, antes da reescrita concorrente das 22:43), para reproduzir os achados."""

from __future__ import annotations

from Bio.Phylo.BaseTree import Clade, Tree

ROTULOS_PADRAO = ("alrt", "abayes", "ufboot")


def _suporte(clade: Clade, rotulos: tuple[str, ...]) -> tuple[float | None, float | None]:
    rotulo = clade.name if clade.name and not clade.is_terminal() else None
    if rotulo and "/" in rotulo:
        partes = rotulo.split("/")
        if len(partes) != len(rotulos):
            return None, None
        try:
            valores = dict(zip(rotulos, (float(p) for p in partes), strict=True))
        except ValueError:
            return None, None
        return valores.get("alrt"), valores.get("ufboot", valores.get("abayes"))
    if clade.confidence is not None:
        return None, float(clade.confidence)
    return None, None


def _forte(sh: float | None, ufb: float | None) -> bool:
    if ufb is None:
        return False
    if ufb <= 1.0 and sh is None:  # probabilidade local do wASTRAL, escala 0-1
        return ufb >= 0.95
    return ufb >= 95 and (sh is None or sh >= 80)


def enraizar(arv: Tree, outgroup: str) -> str:
    nomes = {t.name for t in arv.get_terminals()}
    presentes = [o.strip() for o in outgroup.split(",") if o.strip() in nomes]
    if not presentes:
        arv.root_at_midpoint()
        return ""
    arv.root_with_outgroup(presentes[0])
    if len(presentes) > 1:
        arv.root_with_outgroup(arv.common_ancestor(*presentes))
    return ",".join(presentes)


def rotulo_ramo(c: Clade, rotulos) -> str | None:
    if c.is_terminal():
        return None
    sh, ufb = _suporte(c, rotulos)
    if ufb is None or _forte(sh, ufb):
        return None
    if sh is not None:
        return f"{sh:g}/{ufb:g}"
    return f"{ufb:.2f}" if ufb <= 1.0 else f"{ufb:g}"


