import struct, sys, urllib.request
def rng(url, a, b):
    req=urllib.request.Request(url, headers={'Range':f'bytes={a}-{b}'})
    return urllib.request.urlopen(req, timeout=60).read()
def chroms(url):
    h=rng(url,0,63)
    magic,ver,zl,ctoff,fdoff,fioff=struct.unpack('<IHHQQQ',h[:32])
    t=rng(url,ctoff,ctoff+32+4*1024*1024)
    m,bs,ks,vs,ic=struct.unpack('<IIIIQ',t[:24])
    out=[]
    def node(off):
        isleaf,_,cnt=struct.unpack('<BBH',t[off:off+4]); p=off+4
        for i in range(cnt):
            key=t[p:p+ks].rstrip(b'\x00').decode(); p+=ks
            if isleaf:
                cid,csz=struct.unpack('<II',t[p:p+8]); p+=8; out.append((key,csz))
            else:
                (child,)=struct.unpack('<Q',t[p:p+8]); p+=8; node(child-ctoff)
    node(32)
    return hex(magic), ic, out
