import re
def parse(s):
    s = s.strip().rstrip(';')
    pos = 0
    def node():
        nonlocal pos
        kids = []
        if s[pos] == '(':
            pos += 1
            while True:
                kids.append(node())
                if s[pos] == ',': pos += 1; continue
                if s[pos] == ')': pos += 1; break
        m = re.match(r"[^(),;]*", s[pos:]); lab = m.group(0); pos += len(lab)
        return (kids, lab)
    return node()
def splits(t):
