texto = lock_path.read_text(encoding="utf-8")
# so a secao packages: (a lista do ambiente repete as URLs)
secao = texto.split("\npackages:\n", 1)[1]
urls = re.findall(r"^- conda: (\S+)$", secao, flags=re.M)
lock = {}
for u in urls:
    canal = u.split("/")[3]
    arq = u.rsplit("/", 1)[1]
    for ext in (".conda", ".tar.bz2"):
        if arq.endswith(ext):
            arq = arq[: -len(ext)]
    nome, versao, build = arq.rsplit("-", 2)
    lock[nome] = (versao, build, canal)
print(f"pacotes no lock: {len(lock)}")

cfg = tomllib.loads(manifesto_path.read_text(encoding="utf-8"))
pedidos = {}
for env, spec in cfg["envs"].items():
    for pac, ver in spec["dependencies"].items():
        pedidos[pac] = (env, ver)
print(f"ambientes no manifesto: {len(cfg['envs'])}; pacotes: {len(pedidos)}")

snap = {}
for linha in snapshot_path.read_text(encoding="utf-8").splitlines()[1:]:
    amb, pac, ver, build, canal, _sha = linha.split("\t")
    snap[pac] = (ver, build, canal, amb)
canais = {}
