"""Mede o intervalo LPL-PSD3 no jacare e no frango, com extremidades e orientacao.

A pergunta: o cluster de esmalte do jacare esta DENTRO do intervalo LPL-PSD3 ou
ao lado dele? E o intervalo homologo no frango encurtou?

Sem isso, a afirmacao sobre a cicatriz de delecao nao e verificavel.
"""

from __future__ import annotations

import time

import requests

API = "https://api.ncbi.nlm.nih.gov/datasets/v2alpha"
S = requests.Session()
S.headers["User-Agent"] = "bio-stack/sintenia"


def intervalo(simbolo: str, taxon: int, assembly: str | None):
    url = f"{API}/gene/symbol/{simbolo}/taxon/{taxon}"
    try:
        dados = S.get(url, params={"returned_content": "COMPLETE"}, timeout=90).json()
    except requests.RequestException:
        return None
    for rep in dados.get("reports", []):
        g = rep.get("gene", {})
        if g.get("symbol", "").upper() != simbolo.upper():
            continue
        for a in g.get("annotations", []):
            if assembly and assembly not in a.get("assembly_name", ""):
                continue
            for gl in a.get("genomic_locations", []):
                gr = gl.get("genomic_range", {})
                return {
                    "seq": gl.get("sequence_name"),
                    "ini": int(gr.get("begin", 0)),
                    "fim": int(gr.get("end", 0)),
                    "ori": gr.get("orientation", "?"),
                }
    return None


def relatar(titulo: str, taxon: int, assembly: str | None, simbolos: list[str]):
    print(f"\n{'=' * 74}\n{titulo}\n{'=' * 74}")
    achados = {}
    for sym in simbolos:
        iv = intervalo(sym, taxon, assembly)
        if iv:
            achados[sym] = iv
            tam = abs(iv["fim"] - iv["ini"])
            print(f"  {sym:8s} seq={iv['seq']:4s} {iv['ini']:>13,} .. {iv['fim']:>13,} "
                  f"({iv['ori']:>7s}) tamanho={tam:>9,} bp")
        else:
            print(f"  {sym:8s} NAO ANOTADO")
        time.sleep(0.4)
    return achados


