    return "ave x tartaruga (indep.)"  # perdas independentes: o controle


def cauda_poisson(obs: int, lam: float) -> float:
    """P(X >= obs) para X ~ Poisson(lam)."""
    return 1.0 - sum(math.exp(-lam) * lam**k / math.factorial(k) for k in range(obs))


